165	    // ---- Cargo / crates.io -------------------------------------------
166	
167	    /// Publishes a crate via `cargo publish`.
168	    ///
169	    /// When `registry` is `Some`, `--registry <name>` is appended so that
170	    /// private registries (e.g. Cloudsmith, Artifactory) are targeted instead
171	    /// of crates.io.
172	    fn cargo_publish(&self, package: &PackageId, registry: Option<&str>) -> Result<PublishOutcome, RegistryError> {
173	        if package.name().starts_with('-') {
174	            return Err(RegistryError::Other(format!(
175	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
176	                package.name()
177	            )));
178	        }
179	
180	        // Pre-publish version sanity check: if load_plan provided a package
181	        // directory, read the on-disk Cargo.toml and verify its version matches
182	        // the planned version before invoking `cargo publish`. This catches the
183	        // common mistake of running `callisto publish` without first running
184	        // `callisto version`, which would silently publish the old version.
185	        if let (Some(pkg_dir), Some(planned)) = (
186	            self.cargo_pkg_dir.get(package.name()),
187	            self.cargo_planned_version.get(package.name()),
188	        ) {
189	            let manifest_path = self.cwd.join(pkg_dir).join("Cargo.toml");
190	            // Parse only the [package].version field — no need for full CST.
191	            // Use a permissive `toml::Value` intermediate rather than
192	            // deserializing straight into `String`: `version.workspace = true`
193	            // (Cargo's workspace-version-inheritance syntax) parses `version`
194	            // as a table, not a string, and a direct `String` deserialization
195	            // would fail with "invalid type: map, expected a string" on every
196	            // crate using that pattern.
197	            let contents = std::fs::read_to_string(&manifest_path).map_err(|e| {
198	                RegistryError::Other(format!(
199	                    "could not read `{}` for pre-publish version check: {e}. \
200	                         Ensure the package_dir in the publish plan points to the \
201	                         individual crate directory, not the workspace root.",
202	                    manifest_path.display(),
203	                ))
204	            })?;
205	            let parsed = toml::from_str::<toml::Value>(&contents).map_err(|e| {
206	                RegistryError::Other(format!(
207	                    "could not parse `{}` for pre-publish version check: {e}. \
208	                     The file must contain a [package].version field. \
209	                     If this is a workspace Cargo.toml, set package_dir to the \
210	                     individual crate subdirectory instead.",
211	                    manifest_path.display(),
212	                ))
213	            })?;
214	            let version_value = parsed.get("package").and_then(|p| p.get("version")).ok_or_else(|| {
215	                RegistryError::Other(format!(
216	                    "could not find [package].version in `{}` for pre-publish version check. \
217	                     The file must contain a [package].version field. \
218	                     If this is a workspace Cargo.toml, set package_dir to the \
219	                     individual crate subdirectory instead.",
220	                    manifest_path.display(),
221	                ))
222	            })?;
223	            let on_disk = if let Some(s) = version_value.as_str() {
224	                s.to_string()
225	            } else if version_value.get("workspace").and_then(|w| w.as_bool()) == Some(true) {
226	                let root_manifest_path = self.cwd.join("Cargo.toml");
227	                let resolver = WorkspaceCargoResolver::load(&root_manifest_path).map_err(|e| {
228	                    RegistryError::Other(format!(
229	                        "`{}` has version.workspace = true but the workspace root `{}` \
230	                             could not be loaded to resolve it: {e}",
231	                        manifest_path.display(),
232	                        root_manifest_path.display(),
233	                    ))
234	                })?;
235	                let ws_version = resolver
236	                    .workspace_version()
237	                    .map_err(|e| {
238	                        RegistryError::Other(format!(
239	                            "could not resolve [workspace.package].version from `{}` \
240	                             for `{}`: {e}",
241	                            root_manifest_path.display(),
242	                            manifest_path.display(),
243	                        ))
244	                    })?
245	                    .ok_or_else(|| {
246	                        RegistryError::Other(format!(
247	                            "`{}` has version.workspace = true but the workspace root `{}` \
248	                             has no [workspace.package].version",
249	                            manifest_path.display(),
250	                            root_manifest_path.display(),
251	                        ))
252	                    })?;
253	                ws_version.render().to_string()
254	            } else {
255	                return Err(RegistryError::Other(format!(
256	                    "could not parse [package].version in `{}` for pre-publish version \
257	                     check: expected a string or a `{{ workspace = true }}` table.",
258	                    manifest_path.display(),
259	                )));
260	            };
261	            let expected = planned.render();
262	            if on_disk != expected {
263	                return Err(RegistryError::Other(format!(
264	                    "version mismatch for `{}`: Cargo.toml on disk has version `{}` \
265	                     but the publish plan expects `{}`. \
266	                     Run `callisto version` first to write the new version to disk.",
267	                    package.name(),
268	                    on_disk,
269	                    expected,
270	                )));
271	            }
272	        }
273	
274	        let output = if let Some(reg) = registry {
275	            self.run(
276	                "cargo",
277	                &["publish", "-p", package.name(), "--locked", "--registry", reg],
278	            )?
279	        } else {
280	            self.run("cargo", &["publish", "-p", package.name(), "--locked"])?
281	        };
282	        classify_cargo_output(&output)
283	    }
