285	    // ---- npm ------------------------------------------------------------
286	
287	    fn npm_is_published(
288	        &self,
289	        package: &PackageId,
290	        version: &Version,
291	        registry: Option<&str>,
292	    ) -> Result<bool, RegistryError> {
293	        let spec = format!("{}@{}", package.name(), version.render());
294	        let output = if let Some(reg) = registry {
295	            self.run_quiet("npm", &["view", &spec, "--json", "--registry", reg])?
296	        } else {
297	            self.run_quiet("npm", &["view", &spec, "--json"])?
298	        };
299	
300	        if output.success() && !output.stdout_trimmed().is_empty() {
301	            return Ok(true);
302	        }
303	        if output.success() && output.stdout_trimmed().is_empty() {
304	            return Ok(false);
305	        }
306	
307	        let combined = combined_lower(&output);
308	        if combined.contains("e404")
309	            || combined.contains("etarget")
310	            || combined.contains("no matching version")
311	            || combined.contains("is not in this registry")
312	        {
313	            return Ok(false);
314	        }
315	
316	        if let Some(err) = detect_rate_limit(&combined) {
317	            return Err(err);
318	        }
319	        if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
320	            return Err(err);
321	        }
322	
323	        // Ambiguous failure: don't silently treat as "not published" — a
324	        // false-negative here would cause a duplicate publish attempt.
325	        Err(RegistryError::Other(format!(
326	            "npm view failed ambiguously (exit {:?}): {}",
327	            output.exit_code,
328	            redact_stderr(output.stderr.trim())
329	        )))
330	    }
