332	    /// Detects the npm-compatible package manager from lockfiles in the
333	    /// workspace root (`self.cwd`) and returns the appropriate program name
334	    /// and base argument list for a publish command.
335	    ///
336	    /// Detection priority: pnpm > yarn > bun > npm (default).
337	    ///
338	    /// | Lockfile present   | Program | Base args                                    |
339	    /// |--------------------|---------|----------------------------------------------|
340	    /// | `pnpm-lock.yaml`   | `pnpm`  | `publish --filter <name>`                    |
341	    /// | `yarn.lock`        | `yarn`  | `workspace <name> npm publish`               |
342	    /// | `bun.lockb`/`.lock`| `bun`   | `publish`                                    |
343	    /// | (none)             | `npm`   | `publish --workspace <name>`                 |
344	    ///
345	    /// `tag` and `access` flags are appended after the base args by the caller
346	    /// ([`Self::npm_publish`]).
347	    fn build_npm_publish_command(
348	        &self,
349	        package_name: &str,
350	        tag: Option<&str>,
351	        access: Option<&str>,
352	        registry: Option<&str>,
353	    ) -> (String, Vec<String>) {
354	        let mut extra: Vec<String> = Vec::new();
355	        if let Some(t) = tag {
356	            extra.push("--tag".to_string());
357	            extra.push(t.to_string());
358	        }
359	        if let Some(av) = access {
360	            extra.push("--access".to_string());
361	            extra.push(av.to_string());
362	        }
363	        if let Some(reg) = registry {
364	            extra.push("--registry".to_string());
365	            extra.push(reg.to_string());
366	        }
367	
368	        if self.cwd.join("pnpm-lock.yaml").exists() {
369	            let mut args = vec![
370	                "publish".to_string(),
371	                "--filter".to_string(),
372	                package_name.to_string(),
373	                // pnpm ≥ 7 refuses to publish from a dirty working tree by
374	                // default. After `callisto version` stages manifest bumps,
375	                // the tree is always dirty until the operator commits, so
376	                // we must bypass the git-status check here.
377	                "--no-git-checks".to_string(),
378	            ];
379	            args.extend(extra);
380	            return ("pnpm".to_string(), args);
381	        }
382	
383	        if self.cwd.join("yarn.lock").exists() {
384	            let mut args = vec![
385	                "workspace".to_string(),
386	                package_name.to_string(),
387	                "npm".to_string(),
388	                "publish".to_string(),
389	            ];
390	            args.extend(extra);
391	            return ("yarn".to_string(), args);
392	        }
393	
394	        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
395	        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
396	        if self.cwd.join("bun.lockb").exists() || self.cwd.join("bun.lock").exists() {
397	            let mut args = vec!["publish".to_string()];
398	            args.extend(extra);
399	            return ("bun".to_string(), args);
400	        }
401	
402	        // Default: npm
403	        let mut args = vec![
404	            "publish".to_string(),
405	            "--workspace".to_string(),
406	            package_name.to_string(),
407	        ];
408	        args.extend(extra);
409	        ("npm".to_string(), args)
410	    }
411	
412	    /// Publishes an npm package using the workspace package manager detected
413	    /// from lockfiles in the workspace root (`self.cwd`).
414	    ///
415	    /// - `tag`: when `Some`, appends `--tag <tag>` (e.g. `"next"` for pre-releases).
416	    ///   Without this, the package manager uses the implicit `"latest"` dist-tag.
417	    /// - `access`: when `Some(NpmAccess::Public)`, appends `--access public`;
418	    ///   when `Some(NpmAccess::Restricted)`, appends `--access restricted`;
419	    ///   when `None`, omits `--access` entirely so the package manager applies
420	    ///   its ecosystem default (`restricted` for `@scoped/packages`, `public`
421	    ///   for unscoped).
422	    fn npm_publish(
423	        &self,
424	        package: &PackageId,
425	        tag: Option<&str>,
426	        access: Option<&NpmAccess>,
427	        registry: Option<&str>,
428	    ) -> Result<PublishOutcome, RegistryError> {
429	        if package.name().starts_with('-') {
430	            return Err(RegistryError::Other(format!(
431	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
432	                package.name()
433	            )));
434	        }
435	        let access_value = access.map(|a| match a {
436	            NpmAccess::Public => "public",
437	            NpmAccess::Restricted => "restricted",
438	        });
439	        let (program, args_owned) = self.build_npm_publish_command(package.name(), tag, access_value, registry);
440	        let args_refs: Vec<&str> = args_owned.iter().map(|s| s.as_str()).collect();
441	
442	        // bun publish must run from the package directory — it has no
443	        // --filter or --workspace flag to target a named package. All other
444	        // package managers (pnpm --filter, yarn workspace, npm --workspace)
445	        // run from the workspace root and select the package by name.
446	        let effective_cwd = if program == "bun" {
447	            self.npm_pkg_dir
448	                .get(package.name())
449	                .map(|rel| self.cwd.join(rel))
450	                .unwrap_or_else(|| self.cwd.clone())
451	        } else {
452	            self.cwd.clone()
453	        };
454	
455	        let output = self.run_in(&program, &args_refs, &effective_cwd)?;
456	        classify_npm_publish_output(&output)
457	    }
458	
459	    // ---- PyPI -------------------------------------------------------------
460	
461	    /// Uploads a Python distribution to PyPI (or compatible index) via `twine
462	    /// upload --skip-existing dist/<normalized-name>-<version>*`.
463	    ///
464	    /// Package name is normalized to PEP 427 wheel-filename form (lowercased,
465	    /// `-`/`.` -> `_`) before building the glob. `twine` expands the glob
466	    /// internally -- no shell expansion, so the literal `*` is safe.
467	    ///
468	    /// `index: Some` inserts `--repository-url <url>` before the glob, to
469	    /// target a private index (Nexus/Artifactory PyPI proxy) instead of
470	    /// public PyPI.
471	    ///
472	    /// Output classification via [`classify_twine_output`]: `--skip-existing`'s
473	    /// "already exists" message -> [`PublishOutcome::AlreadyPublished`]; clean
474	    /// zero-exit with no skip message -> [`PublishOutcome::Published`];
475	    /// rate-limit/auth signals -> matching [`RegistryError`] variants;
476	    /// everything else -> [`RegistryError::Other`].
477	    fn pypi_publish(
478	        &self,
479	        package: &PackageId,
480	        version: &Version,
481	        index: Option<&str>,
482	    ) -> Result<PublishOutcome, RegistryError> {
483	        if package.name().starts_with('-') {
484	            return Err(RegistryError::Other(format!(
485	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
486	                package.name()
487	            )));
488	        }
489	        let normalized = normalize_pypi_package_name(package.name());
490	        let pattern = format!("dist/{normalized}-{}*", version.render());
491	
492	        // Both build and upload run from the package directory so that `dist/`
493	        // resolves to the package's own dist/ folder. When no package_dir was
494	        // stored by load_plan (e.g. tests that call this method directly),
495	        // fall back to the workspace root.
496	        let pkg_cwd = self
497	            .pypi_pkg_dir
498	            .get(package.name())
499	            .map(|rel| self.cwd.join(rel))
500	            .unwrap_or_else(|| self.cwd.clone());
501	
502	        // Build step (spec §8.3): produce the sdist and wheel before uploading.
503	        // Build failures are not transient registry errors — do NOT retry them.
504	        let build_out = self.run_in(
505	            "python",
506	            &["-m", "build", "--sdist", "--wheel", "--outdir", "dist/"],
507	            &pkg_cwd,
508	        )?;
509	        if !build_out.success() {
510	            return Err(RegistryError::Other(format!(
511	                "python -m build failed for `{}` (exit {:?}): {}",
512	                package.name(),
513	                build_out.exit_code,
514	                redact_stderr(build_out.stderr.trim())
515	            )));
516	        }
517	
518	        let output = if let Some(idx) = index {
519	            self.run_in(
520	                "twine",
521	                &["upload", "--skip-existing", "--repository-url", idx, &pattern],
522	                &pkg_cwd,
523	            )?
524	        } else {
525	            self.run_in("twine", &["upload", "--skip-existing", &pattern], &pkg_cwd)?
526	        };
527	        classify_twine_output(&output)
528	    }
529	}
