1048	    /// `npm view`'s 404-shaped "not published yet" failure is the expected,
1049	    /// routine outcome of this existence-check probe -- it must not stream
1050	    /// live to the terminal the way a real, user-facing `npm publish` call
1051	    /// does. Distinguishes `run_quiet` from `run`/`run_with_timeout` by
1052	    /// tracking which one the underlying `CommandRunner` actually receives.
1053	    struct QuietTrackingRunner {
1054	        quiet_called: std::sync::atomic::AtomicBool,
1055	        live_called: std::sync::atomic::AtomicBool,
1056	        response: CommandOutput,
1057	    }
1058	
1059	    impl CommandRunner for QuietTrackingRunner {
1060	        fn run(&self, _program: &str, _args: &[&str], _cwd: &std::path::Path) -> Result<CommandOutput, CommandError> {
1061	            self.live_called.store(true, std::sync::atomic::Ordering::SeqCst);
1062	            Ok(self.response.clone())
1063	        }
1064	
1065	        fn run_with_timeout(
1066	            &self,
1067	            _program: &str,
1068	            _args: &[&str],
1069	            _cwd: &std::path::Path,
1070	            _timeout: Duration,
1071	        ) -> Result<CommandOutput, CommandError> {
1072	            self.live_called.store(true, std::sync::atomic::Ordering::SeqCst);
1073	            Ok(self.response.clone())
1074	        }
1075	
1076	        fn run_quiet(
1077	            &self,
1078	            _program: &str,
1079	            _args: &[&str],
1080	            _cwd: &std::path::Path,
1081	            _timeout: Duration,
1082	        ) -> Result<CommandOutput, CommandError> {
1083	            self.quiet_called.store(true, std::sync::atomic::Ordering::SeqCst);
1084	            Ok(self.response.clone())
1085	        }
1086	    }
