1233	    type OrderedCallLog = std::sync::Arc<std::sync::Mutex<Vec<(String, Vec<String>)>>>;
1234	
1235	    /// Records every (program, args) call in order. Used to verify call
1236	    /// sequencing: python -m build must appear before twine upload.
1237	    struct OrderedCallCapture {
1238	        #[allow(clippy::type_complexity)]
1239	        calls: OrderedCallLog,
1240	        response: CommandOutput,
1241	    }
1242	
1243	    impl CommandRunner for OrderedCallCapture {
1244	        fn run(&self, program: &str, args: &[&str], _cwd: &std::path::Path) -> Result<CommandOutput, CommandError> {
1245	            self.calls
1246	                .lock()
1247	                .unwrap()
1248	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
1249	            Ok(self.response.clone())
1250	        }
1251	    }
1252	
1253	    /// Spec §8.3: python -m build MUST be called before twine upload.
1254	    /// On a clean checkout there is no dist/ directory; skipping the build
1255	    /// step causes twine to fail with "Cannot find file (or expand pattern)".
1256	    #[test]
1257	    fn pypi_publish_runs_python_build_before_twine() {
1258	        let calls = std::sync::Arc::new(std::sync::Mutex::new(Vec::<(String, Vec<String>)>::new()));
1259	        let runner = OrderedCallCapture {
1260	            calls: std::sync::Arc::clone(&calls),
1261	            response: output(0, "Uploading my_lib-1.2.3-py3-none-any.whl\n", ""),
1262	        };
1263	        let c = SubprocessRegistryClient::new(runner, PathBuf::from("/workspace"));
1264	        c.publish(&pypi_pkg(), &v1(), &permit()).unwrap();
